const root = items[0].json || {}
const body = root.body || root
const action = body.action === 'delete' ? 'delete' : 'publish'
const token = String($env.TELEGRAM_NEWS_BOT_TOKEN || '')
const chatId = String(body.chatId || $env.TELEGRAM_NEWS_CHANNEL_ID || '').trim()
const base = String($env.TELEGRAM_API_BASE || 'https://api.telegram.org').replace(/\/$/, '')
const proxyToken = base.includes('api.telegram.org') ? '' : String($env.GEMINI_PROXY_TOKEN || '')

function done(ok, published, failed, deleted) {
  return [{ json: { skip: true, ok, published, failed, deleted, rollback: null } }]
}

if (!token) return done(false, [], { handle: '', message: 'News bot token is not set' }, 0)
if (!chatId) return done(false, [], { handle: '', message: 'Archive channel is not configured' }, 0)

function urlFor(method) {
  return base + '/bot' + token + '/' + method
}

if (action === 'delete') {
  const ids = Array.isArray(body.messageIds) ? body.messageIds : []
  if (ids.length === 0) return done(true, [], null, 0)
  return ids.map((messageId) => ({
    json: {
      skip: false,
      mode: 'json',
      kind: 'delete',
      chatId,
      url: urlFor('deleteMessage'),
      proxyToken,
      payload: { chat_id: chatId, message_id: messageId },
    },
  }))
}

const calls = []
const channels = Array.isArray(body.channels) ? body.channels : []
for (let channelIndex = 0; channelIndex < channels.length; channelIndex += 1) {
  const channel = channels[channelIndex] || {}
  const handle = String(channel.handle || '')
  const posts = Array.isArray(channel.posts) ? channel.posts : []
  for (let postIndex = 0; postIndex < posts.length; postIndex += 1) {
    const post = posts[postIndex] || {}
    const text = String(post.text || '').trim()
    const media = (Array.isArray(post.media) ? post.media : []).filter((item) => item && item.url).slice(0, 10)
    calls.push({
      json: {
        skip: false,
        mode: 'json',
        kind: 'publish',
        handle,
        telegramPostId: post.telegramPostId,
        chatId,
        url: 'http://host.docker.internal:3010/api/internal/news-archive/send',
        serviceToken: String($env.INTERNAL_SERVICE_TOKEN || ''),
        proxyToken: '',
        payload: { chatId, handle, telegramPostId: post.telegramPostId, text, media },
      },
    })
  }
}

if (calls.length === 0) return done(true, [], null, 0)
return calls

let source = {}
try {
  source = $('По одному').item.json || {}
} catch (error) {
  source = {}
}
const item = items[0]
const binary = item.binary && item.binary.data
const mime = binary && binary.mimeType ? String(binary.mimeType) : ''
if (!binary || mime.includes('text/html')) {
  const previous = item.json && (item.json.description || (item.json.error && item.json.error.message) || '')
  item.json = {
    ok: false,
    description: String(previous || 'Could not download the post media').replace(/https?:\/\/\S+/g, '[url]').slice(0, 300),
  }
  return [item]
}
const video = source.field === 'video'
binary.fileName = video ? 'clip.mp4' : 'photo.jpg'
if (!mime || mime.includes('octet-stream')) binary.mimeType = video ? 'video/mp4' : 'image/jpeg'
return [item]

const prepared = $('Подготовить вызовы').all().map((item) => item.json).filter((item) => !item.skip)
const source = prepared[Number.isInteger($runIndex) ? $runIndex : prepared.length] || {}
const response = (items[0] && items[0].json) || {}
const payload = source.payload || {}
const tooFast = /spacing your requests|too many requests|retry after/i.test(JSON.stringify(response).slice(0, 400))
await new Promise((resolve) => setTimeout(resolve, tooFast ? 5000 : 3000))
return [{
  json: {
    kind: source.kind || '',
    handle: source.handle || '',
    telegramPostId: source.telegramPostId,
    media: source.media || [],
    chatId: String(source.chatId || payload.chat_id || ''),
    response,
  },
}]

function clean(value) {
  return String(value || '').replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot').replace(/https?:\/\/\S+/g, '[url]').slice(0, 300)
}

function fileId(message, kind) {
  if (!message) return ''
  if (kind === 'video') return message.video && message.video.file_id ? message.video.file_id : ''
  const photos = message.photo || []
  return photos.length ? photos[photos.length - 1].file_id : ''
}

const rows = items.map((item) => item.json)
const published = []
let deleted = 0
let current = null

function flush() {
  if (!current) return
  published.push(current)
  current = null
}

function fail(source, message) {
  const rollback = current && current.messageIds.length
    ? { chatId: current.chatId, messageIds: current.messageIds.slice() }
    : null
  current = null
  return [{
    json: {
      ok: false,
      published,
      failed: { handle: source.handle || '', message },
      deleted,
      rollback,
    },
  }]
}

for (let index = 0; index < rows.length; index += 1) {
  const source = rows[index] || {}
  const response = source.response || {}
  const missing = /message to delete not found|message identifier is not specified|message_id_invalid/i
  if (response.ok !== true) {
    const message = clean(response.description || (response.error && response.error.message) || 'Telegram request failed')
    if (source.kind === 'delete' && missing.test(message)) {
      deleted += 1
      continue
    }
    return fail(source, message)
  }
  if (source.kind === 'delete') {
    deleted += 1
    continue
  }
  if (Array.isArray(response.messageIds)) {
    const directIds = response.messageIds.filter((id) => Number.isInteger(id))
    if (directIds.length === 0) return fail(source, 'Telegram did not return a message id')
    published.push({
      handle: source.handle,
      telegramPostId: source.telegramPostId,
      chatId: String(response.chatId || source.chatId || ''),
      messageIds: directIds,
      media: Array.isArray(response.media) ? response.media.filter((item) => item && item.fileId) : [],
    })
    continue
  }
  const result = response.result
  const messages = Array.isArray(result) ? result : [result]
  const messageIds = messages.map((message) => message && message.message_id).filter((id) => Number.isInteger(id))
  if (messageIds.length === 0) return fail(source, 'Telegram did not return a message id')
  const chatId = String(messages[0] && messages[0].chat ? messages[0].chat.id : source.chatId)
  const same = current && current.handle === source.handle && current.telegramPostId === source.telegramPostId
  if (!same) {
    flush()
    current = { handle: source.handle, telegramPostId: source.telegramPostId, chatId, messageIds: [], media: [] }
  }
  current.messageIds.push.apply(current.messageIds, messageIds)
  const kinds = source.media || []
  for (let mediaIndex = 0; mediaIndex < kinds.length; mediaIndex += 1) {
    const id = fileId(messages[mediaIndex] || messages[0], kinds[mediaIndex])
    if (id) current.media.push({ kind: kinds[mediaIndex], fileId: id })
  }
}

flush()
return [{ json: { ok: true, published, failed: null, deleted, rollback: null } }]
